/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: ImportAutomationPlan, ImportAutomationOutcome
 *   Functions: discFromRelativePath, planImportAutomation, runImportAutomation
 *   Constants: AUTOMATIC_ENTRY_SEED
 * Internal
 *   Functions: evidence, shared
 *   Constants: discSegment
 * @end-catalog */

/**
 * The only automatic writer of Draft v2 values, from version-2 file-tag evidence through applyAutomaticValues. Owner rules:
 * docs/business-rules.md (Administrator Album Imports, tag-evidence and value-origin bullets).
 */
import { ObjectId } from 'mongodb';
import { objectId, type ImportTagsView } from './adminImportContract';
import { derivedEntryKey, retainBoundDecisions, type ImportArtistEntry, type ImportDraftV2 } from './adminImportDraft';
import { importDraftWritable } from './adminImportDraftCompat';
import { importSourcesLocked, type ImportAsset } from './adminImportMediaTypes';
import { importCollection, importPurposeFilter, isDraftV2Document, isImportProject, withImportAdmin, type AdminImportDocument } from './adminImportService';
import { importTagsV2View } from './adminImportTags';
import { applyAutomaticValues, draftValueAt, storedDraftV2, type ImportAutomaticSkip, type ImportAutomaticValue, type ImportDraftPath } from './adminImportValueState';
import { isPlaceholderCredit } from '../lookup/lookupIdentifiers';

/** What one run would write: the confirmed files whose per-file step is due, whether the album step is due, and the values. */
export type ImportAutomationPlan = { files: { slotId: string; operationId: string }[]; album: boolean; values: ImportAutomaticValue[] };
export type ImportAutomationOutcome = { ran: boolean; written: ImportDraftPath[]; skipped: ImportAutomaticSkip[]; album: boolean };
/** Seed of the one primary entry the album step writes from a shared album artist, so its key is stable per import. */
export const AUTOMATIC_ENTRY_SEED = 'albumArtist';

const discSegment = /^(?:disc|disk|cd)[\s._-]*0*(\d{1,3})(?=$|[\s._\-)\]])/i;
/**
 * The Disc Number a relative path names in a folder (`Disc 2/`, `CD2/`) or at the start of its file name (`CD2-01 x.flac`): 1 to
 * 999, and only when every match agrees. Words that merely start alike (`Discography`, `Disco 2000`) never match. Pure.
 */
export function discFromRelativePath(relativePath: string): number | null {
    const found = new Set<number>();
    for (const segment of relativePath.split('/')) {
        const match = discSegment.exec(segment), disc = match ? Number(match[1]) : 0;
        if (disc >= 1 && disc <= 999) found.add(disc);
    }
    return found.size === 1 ? [...found][0] : null;
}

/** Version-2 evidence of a confirmed asset, read through the allowlist; evidence stored before S8 contributes nothing. */
const evidence = (asset: ImportAsset | undefined): ImportTagsView | null => {
    const tags = asset?.state === 'ready' ? importTagsV2View(asset.tags) : null;
    return tags?.version === 2 ? tags : null;
};
/** The value every file carries, or null when one lacks it or two disagree. */
function shared<T>(all: readonly ImportTagsView[], pick: (tags: ImportTagsView) => T | null): T | null {
    const values = all.map(pick);
    return values.length > 0 && values.every(value => value !== null && value === values[0]) ? values[0] : null;
}

/**
 * Plans one run against a Draft v2 import project (pure). The per-file step covers each manifest slot whose ready asset has
 * version-2 evidence and has not been automated: its title, Disc Number (the tag, else the relative path) and Track Number. The
 * album step runs once, after every manifest slot is ready with version-2 evidence: the Album title, year and label all files
 * share, and one primary Artist entry from an album artist every file names alone, with no album-artist name left out. A missing or disagreeing value, a placeholder
 * credit or no evidence plans nothing for that value. Each value's `seen` is its current value, so applyAutomaticValues writes it
 * only into an empty or automatic value nobody changed.
 */
export function planImportAutomation(doc: AdminImportDocument): ImportAutomationPlan {
    const plan: ImportAutomationPlan = { files: [], album: false, values: [] };
    if (!isDraftV2Document(doc) || !isImportProject(doc)) return plan;
    let draft: ImportDraftV2; try { draft = storedDraftV2(doc); } catch { return plan; }
    const add = (path: ImportDraftPath, value: unknown) => {
        if (value === null) return;
        // A path the stored draft lacks is malformed; it is left for a reload rather than written.
        try { plan.values.push({ path, seen: structuredClone(draftValueAt(draft, path)), value }); } catch { /* skipped */ }
    };
    const assets = doc.media?.assets ?? [], readyAsset = (slotId: string) => assets.find(asset => asset.slotId === slotId && asset.state === 'ready');
    for (const file of doc.manifest.files) {
        const asset = readyAsset(file.slotId), tags = evidence(asset);
        if (!asset || !tags || asset.automatedAt) continue;
        plan.files.push({ slotId: file.slotId, operationId: asset.operationId });
        add(`tracks.${file.slotId}.title`, tags.title);
        add(`tracks.${file.slotId}.discNumber`, tags.discNumber ?? discFromRelativePath(file.relativePath));
        add(`tracks.${file.slotId}.trackNumber`, tags.trackNumber);
    }
    const all = doc.manifest.files.map(file => evidence(readyAsset(file.slotId)));
    if (doc.automation?.albumAt || !all.length || all.some(tags => tags === null)) return plan;
    const files = all as ImportTagsView[];
    plan.album = true;
    add('album.title', shared(files, tags => tags.album));
    const year = shared(files, tags => tags.year);
    add('album.releaseDate', year === null ? null : { year, month: null, day: null });
    const label = shared(files, tags => tags.label);
    add('album.label', label === null || isPlaceholderCredit(label) ? null : { name: label, musicBrainzId: null });
    // A file whose album-artist list lost a flagged name names no album artist, so a partial list never passes as the only one.
    const artist = shared(files, tags => tags.albumArtists.length === 1 && !tags.flagged.some(item => item.field === 'albumArtists') ? tags.albumArtists[0] : null);
    const entry: ImportArtistEntry | null = artist === null || isPlaceholderCredit(artist) ? null
        : { key: derivedEntryKey({ importId: doc._id.toHexString(), automatic: AUTOMATIC_ENTRY_SEED }), name: artist, role: 'primary', joinPhrase: null, musicBrainzId: null };
    add('album.artists', entry && [entry]);
    return plan;
}

/**
 * Runs due automation for one import as `actor`, in one transaction that checks the role and fences the actor. Nothing is written
 * unless the project is a writable Draft v2 import whose sources no publication locks. Planned assets are marked automated and
 * the album step is marked done even when values are skipped (partial success), so a retry never runs a step twice; a write bumps
 * only `valueRevision`, never `revision`, receipts or the editing allowance. A concurrent writer is a WriteConflict that
 * withTransaction retries against fresh state. Never throws: permission loss, exhausted retries or a malformed draft write nothing,
 * and the upload or reconciliation that triggered it keeps its own result.
 */
export async function runImportAutomation(actor: string, id: string): Promise<ImportAutomationOutcome> {
    const idle: ImportAutomationOutcome = { ran: false, written: [], skipped: [], album: false };
    if (!objectId(id)) return idle;
    try {
        return await withImportAdmin(actor, async session => {
            const doc = await importCollection().findOne({ _id: new ObjectId(id), ...importPurposeFilter }, { session });
            if (!doc || !isDraftV2Document(doc) || !importDraftWritable(doc) || importSourcesLocked(doc.media) || doc.catalogApplied) return idle;
            const plan = planImportAutomation(doc);
            if (!plan.files.length && !plan.album) return idle;
            const draft = storedDraftV2(doc), now = new Date();
            const result = applyAutomaticValues({ draft, draftOrigins: doc.draftOrigins ??= {} }, plan.values);
            for (const file of plan.files) {
                const asset = doc.media?.assets.find(item => item.slotId === file.slotId && item.operationId === file.operationId);
                if (asset) asset.automatedAt = now;
            }
            // Markers a later release keeps beside albumAt survive (a release never drops stored state it does not know).
            if (plan.album) doc.automation = { ...doc.automation, albumAt: now };
            if (result.written.length) {
                doc.decisions = retainBoundDecisions(doc.decisions, draft);
                doc.valueRevision = (Number.isSafeInteger(doc.valueRevision) && doc.valueRevision! >= 0 ? doc.valueRevision! : 0) + 1;
                doc.updatedAt = now;
            }
            const update = await importCollection().replaceOne({ _id: doc._id, revision: doc.revision }, doc, { session });
            return update.matchedCount === 1 ? { ran: true, written: result.written, skipped: result.skipped, album: plan.album } : idle;
        });
    } catch { return idle; }
}
